insert into public.passages (id, subject, grade_level, title, body, owner_id, source) values ('p-amina-seedlings', 'reading', 5, 'Amina and the Seedlings', 'Before the class arrived, Amina noticed that the seedlings beside the window were drooping and their soil was dry. She filled a small jug and watered them. At lunch, she checked the soil again and moved the tray away from the hot window.', null, 'seed') on conflict (id) do update set title = excluded.title, body = excluded.body;
insert into public.passages (id, subject, grade_level, title, body, owner_id, source) values ('p-leo-frost', 'reading', 5, 'Leo''s Morning', 'Before leaving for school, Leo saw frost on the grass. He opened the door, stepped outside, then went back in and exchanged his thin jacket for a thick coat.', null, 'seed') on conflict (id) do update set title = excluded.title, body = excluded.body;
insert into public.passages (id, subject, grade_level, title, body, owner_id, source) values ('p-kofi-bake-sale', 'reading', 5, 'The Bake Sale', 'Kofi set out three trays of muffins at the school bake sale. By ten o''clock, two trays were empty and people were still lining up. Kofi texted his dad, who started mixing more batter at home.', null, 'seed') on conflict (id) do update set title = excluded.title, body = excluded.body;
insert into public.passages (id, subject, grade_level, title, body, owner_id, source) values ('p-priya-garden', 'reading', 5, 'Priya''s Garden', 'Priya looked out at the garden and saw that the tomatoes on the vines had turned bright red. She grabbed an empty basket and headed outside.', null, 'seed') on conflict (id) do update set title = excluded.title, body = excluded.body;
insert into public.passages (id, subject, grade_level, title, body, owner_id, source) values ('p-mateo-rain', 'reading', 5, 'Mateo''s Library Book', 'Mateo looked out the window and saw that it was pouring. He zipped up his raincoat, tucked his library book inside it, and ran all the way to the library.', null, 'seed') on conflict (id) do update set title = excluded.title, body = excluded.body;
insert into public.passages (id, subject, grade_level, title, body, owner_id, source) values ('p-patel-card', 'reading', 5, 'Welcome Back', 'When Ms. Patel walked into the classroom on Monday, every student was sitting quietly. The chairs were pushed in, the floor was clean, and a big card that said "Get Well Soon" was waiting on her desk.', null, 'seed') on conflict (id) do update set title = excluded.title, body = excluded.body;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-read-inf-unsupported', 'reading', 'reading.inference', 'targeted', 'UNSUPPORTED_INFERENCE', 'Let the clues do the talking', array['A good inference is a smart guess that the clues in the passage support.', 'If a reason uses a detail the passage never gives, it might be a story we made up instead of an inference.', 'Check each part of your reason: can you point to the words in the passage that support it?']::text[], '{"passage":"Tomás looked out the window and saw dark grey clouds filling the sky. The wind was making the trees sway. He took his umbrella from the hook before he left the house.","steps":["Clue 1: \"dark grey clouds filling the sky.\"","Clue 2: \"The wind was making the trees sway.\"","Clue 3: \"He took his umbrella\" before leaving.","Putting the clues together: Tomás most likely expected rain. The passage never says \"it will rain\" — the clues point there.","Not supported: \"He took the umbrella because it was a gift from his grandma.\" Nothing in the passage mentions a gift."]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-read-inf-explicit', 'reading', 'reading.inference', 'targeted', 'EXPLICIT_STATEMENT_REQUIRED', 'Authors leave clues, not always answers', array['Authors don''t always tell us everything directly. Sometimes they leave clues for readers to put together.', 'When a question says "most likely," it is asking you to use the clues to make a reasonable inference.', 'You can be confident in an inference when several clues point the same way.']::text[], '{"passage":"Tomás looked out the window and saw dark grey clouds filling the sky. The wind was making the trees sway. He took his umbrella from the hook before he left the house.","steps":["The passage does not say why Tomás took his umbrella.","But it gives clues: dark grey clouds and strong wind.","People often take umbrellas when they expect rain, and the clues describe weather that often comes before rain.","So we can infer: Tomás most likely expected rain — even though those words never appear."]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-read-inf-general', 'reading', 'reading.inference', 'general', null, 'Clues + what you know = inference', array['To make an inference, find clues in the passage and think about what they suggest together.', 'Then check that your answer is supported by those clues, not by details the passage doesn''t give.']::text[], '{"passage":"Tomás looked out the window and saw dark grey clouds filling the sky. The wind was making the trees sway. He took his umbrella from the hook before he left the house.","steps":["Find the clues: dark grey clouds, wind, taking an umbrella.","Ask: what do these clues suggest together? Rain might be coming.","Inference: Tomás most likely expected rain.","Check: every part of that inference connects to a clue in the passage."]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-read-inf-slip', 'reading', 'reading.inference', 'slip', null, 'Your thinking was on track', array['Your reasoning used clues from the passage — nice work.', 'Before you submit, re-read the answer you picked and make sure it matches what you explained.']::text[], '{"steps":["Read your explanation.","Read each answer choice.","Pick the choice that says the same thing as your explanation."]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-math-frac-larger-denominator', 'math', 'math.fractions_intro', 'targeted', 'LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'More pieces means smaller pieces', array['The denominator (bottom number) tells how many equal parts the whole is cut into.', 'When two wholes are the same size, cutting one into more parts makes each part smaller.', 'So a bigger denominator means smaller pieces — not a bigger amount.']::text[], '{"problem":"Two same-sized chocolate bars. Compare 2/3 of one bar with 2/6 of the other.","steps":["Both bars are the same size.","The first bar is cut into 3 equal parts. The second bar is cut into 6 equal parts.","Three equal parts are larger than six equal parts of the same bar.","Each fraction has 2 parts. Two larger parts are more than two smaller parts.","So 2/3 > 2/6. (Check: 2/3 = 4/6, and 4/6 > 2/6.)"],"fractionBars":[{"label":"2/3 of a chocolate bar","numerator":2,"denominator":3},{"label":"2/6 of a same-sized chocolate bar","numerator":2,"denominator":6}]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-math-frac-same-numerator-equal', 'math', 'math.fractions_intro', 'targeted', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT', 'Same number of pieces, different sizes', array['When the numerators match, both fractions have the same number of pieces.', 'But the pieces might not be the same size! The denominator tells us how big each piece is.', 'Compare the size of the pieces, not just how many there are.']::text[], '{"problem":"Two same-sized chocolate bars. Compare 2/3 of one bar with 2/6 of the other.","steps":["Both fractions have 2 pieces.","In 2/3, each piece is one third of the bar. In 2/6, each piece is one sixth of the bar.","A third is bigger than a sixth when the bars are the same size.","Two thirds is more chocolate than two sixths, so 2/3 > 2/6."],"fractionBars":[{"label":"2/3 of a chocolate bar","numerator":2,"denominator":3},{"label":"2/6 of a same-sized chocolate bar","numerator":2,"denominator":6}]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-math-frac-general', 'math', 'math.fractions_intro', 'general', null, 'Comparing fractions with the same numerator', array['First check: are the wholes the same size? You can only compare this way when they are.', 'If the numerators are the same, look at the denominators to compare the size of each piece.', 'Fewer equal parts means bigger parts, so the fraction with the smaller denominator is larger.']::text[], '{"problem":"Two same-sized chocolate bars. Compare 2/3 of one bar with 2/6 of the other.","steps":["Same-sized wholes? Yes.","Same numerator? Yes — 2 pieces each.","Thirds are bigger pieces than sixths.","So 2/3 > 2/6."],"fractionBars":[{"label":"2/3 of a chocolate bar","numerator":2,"denominator":3},{"label":"2/6 of a same-sized chocolate bar","numerator":2,"denominator":6}]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.practice_resources (id, subject, skill, kind, misconception, title, explanation, worked_example, verified) values ('pr-math-frac-slip', 'math', 'math.fractions_intro', 'slip', null, 'Your method was on track', array['Your explanation shows a good comparison method.', 'Double-check that the name or choice you selected matches the fraction you said was larger.']::text[], '{"steps":["Re-read your explanation.","Find which person''s fraction you said was larger.","Select that person''s choice."]}'::jsonb, true) on conflict (id) do update set title = excluded.title, explanation = excluded.explanation, worked_example = excluded.worked_example, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-inf-leo', 1, 'reading', 5, 'reading.inference', 'Making inferences using textual evidence', 'follow-up', 'p-leo-frost', 'Why did Leo most likely change his jacket?', 'Use a detail from the passage to support your answer.', '[{"id":"A","text":"His thin jacket was torn."},{"id":"B","text":"He expected cold weather."},{"id":"C","text":"His teacher required a thick coat."},{"id":"D","text":"He wanted to carry more books."}]'::jsonb, 'B', 'Frost on the grass and stepping outside before switching to a thick coat suggest Leo felt or expected cold weather. The passage never mentions a torn jacket, a teacher''s rule, or books.', array['UNSUPPORTED_INFERENCE', 'EXPLICIT_STATEMENT_REQUIRED']::text[], 'pr-read-inf-general', null, true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-inf-priya', 1, 'reading', 5, 'reading.inference', 'Making inferences using textual evidence', 'follow-up', 'p-priya-garden', 'What will Priya most likely do next?', 'Use a detail from the passage to support your answer.', '[{"id":"A","text":"Pick the ripe tomatoes."},{"id":"B","text":"Paint the garden fence."},{"id":"C","text":"Plant new seeds because the tomatoes died."},{"id":"D","text":"Water the grass because it is dry."}]'::jsonb, 'A', 'Bright red tomatoes are a clue that they are ripe, and grabbing an empty basket before heading outside suggests she plans to collect them.', array['UNSUPPORTED_INFERENCE', 'EXPLICIT_STATEMENT_REQUIRED']::text[], 'pr-read-inf-general', null, true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-math-frac-ribbon', 1, 'math', 5, 'math.fractions_intro', 'Comparing fractions with the same numerator', 'follow-up', null, 'Two ribbons have the same original length. Sara uses 4/5 of one ribbon. Ben uses 4/9 of the other. Who uses more ribbon?', 'Explain why one fraction represents a larger amount.', '[{"id":"A","text":"Sara."},{"id":"B","text":"Ben."},{"id":"C","text":"They use the same amount."},{"id":"D","text":"It cannot be determined."}]'::jsonb, 'A', 'For equal wholes and the same positive numerator, fifths are larger than ninths, so 4/5 > 4/9.', array['LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT']::text[], 'pr-math-frac-general', null, true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-math-frac-garden', 1, 'math', 5, 'math.fractions_intro', 'Comparing fractions with the same numerator', 'follow-up', null, 'Two garden plots are the same size. Ravi plants beans in 5/6 of one plot. Lena plants beans in 5/8 of the other plot. Who plants beans in more space?', 'Explain why one fraction represents a larger amount.', '[{"id":"A","text":"Lena."},{"id":"B","text":"They use the same amount of space."},{"id":"C","text":"It cannot be determined."},{"id":"D","text":"Ravi."}]'::jsonb, 'D', 'The plots are the same size. Sixths are larger than eighths, so five sixths is more than five eighths: 5/6 > 5/8.', array['LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT']::text[], 'pr-math-frac-general', null, true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-inf-amina', 1, 'reading', 5, 'reading.inference', 'Making inferences using textual evidence', 'initial', 'p-amina-seedlings', 'Why did Amina most likely move the tray away from the window?', 'Which clues in the passage helped you decide?', '[{"id":"A","text":"To hide the plants from her classmates."},{"id":"B","text":"Because the teacher told her to move it."},{"id":"C","text":"To help stop the soil from drying out so quickly."},{"id":"D","text":"Because seedlings never need sunlight."}]'::jsonb, 'C', 'The dry soil, drooping seedlings, and hot window together support the inference that Amina wanted to reduce drying. The passage does not say she was instructed to move them.', array['UNSUPPORTED_INFERENCE', 'EXPLICIT_STATEMENT_REQUIRED']::text[], 'pr-read-inf-general', 'q-read-inf-leo', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-inf-kofi', 1, 'reading', 5, 'reading.inference', 'Making inferences using textual evidence', 'initial', 'p-kofi-bake-sale', 'What can you most likely infer about the muffins?', 'Which details from the passage support your answer?', '[{"id":"A","text":"Nobody liked the muffins."},{"id":"B","text":"Kofi''s dad ate most of the muffins."},{"id":"C","text":"The muffins were being given away for free."},{"id":"D","text":"Many people wanted to buy the muffins."}]'::jsonb, 'D', 'Two of three trays were empty by ten o''clock, people were still lining up, and more batter was being made. Together these clues support the inference that many people wanted the muffins. Nothing in the passage says they were free.', array['UNSUPPORTED_INFERENCE', 'EXPLICIT_STATEMENT_REQUIRED']::text[], 'pr-read-inf-general', 'q-read-inf-priya', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-math-frac-pizza', 1, 'math', 5, 'math.fractions_intro', 'Comparing fractions with the same numerator', 'initial', null, 'Two same-sized pizzas are cut into equal pieces. Mia eats 3/4 of one pizza. Noah eats 3/8 of the other. Who eats more?', 'Explain how the size and number of pieces helped you compare.', '[{"id":"A","text":"Noah."},{"id":"B","text":"Mia."},{"id":"C","text":"They eat the same amount."},{"id":"D","text":"It cannot be determined."}]'::jsonb, 'B', 'The wholes are the same size. Fourths are larger than eighths. Three fourths is therefore greater than three eighths. Equivalently, 3/4 = 6/8 > 3/8.', array['LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT']::text[], 'pr-math-frac-general', 'q-math-frac-ribbon', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-math-frac-juice', 1, 'math', 5, 'math.fractions_intro', 'Comparing fractions with the same numerator', 'initial', null, 'Two same-sized jugs are full of juice. Ella pours out 2/3 of one jug. Sam pours out 2/5 of the other jug. Who pours out more juice?', 'Explain how the size of the parts helped you compare.', '[{"id":"A","text":"Sam."},{"id":"B","text":"They pour out the same amount."},{"id":"C","text":"Ella."},{"id":"D","text":"It cannot be determined."}]'::jsonb, 'C', 'The jugs are the same size. Thirds are larger than fifths, so two thirds is more than two fifths: 2/3 > 2/5.', array['LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT']::text[], 'pr-math-frac-general', 'q-math-frac-garden', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-inf-mateo', 1, 'reading', 5, 'reading.inference', 'Making inferences using textual evidence', 'initial', 'p-mateo-rain', 'Why did Mateo most likely tuck his library book inside his raincoat?', 'Which clues in the passage helped you decide?', '[{"id":"A","text":"He wanted to hide the book from the librarian."},{"id":"B","text":"To keep the book dry."},{"id":"C","text":"Because the book was too heavy to carry."},{"id":"D","text":"Because his teacher told him to."}]'::jsonb, 'B', 'It was pouring, and Mateo put the book inside his raincoat before running outside. These clues support the inference that he wanted to protect the book from the rain. Nothing in the passage mentions hiding, weight, or a teacher.', array['UNSUPPORTED_INFERENCE', 'EXPLICIT_STATEMENT_REQUIRED']::text[], 'pr-read-inf-general', 'q-read-inf-leo', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-inf-patel', 1, 'reading', 5, 'reading.inference', 'Making inferences using textual evidence', 'initial', 'p-patel-card', 'What can you most likely infer about Ms. Patel?', 'Which details from the passage support your answer?', '[{"id":"A","text":"She had just moved to a new school."},{"id":"B","text":"Her students were in trouble."},{"id":"C","text":"She had been sick or unwell."},{"id":"D","text":"She forgot it was Monday."}]'::jsonb, 'C', 'A "Get Well Soon" card is usually given to someone who is or has been sick. The tidy room and quiet students suggest they prepared a kind welcome. The passage gives no clues about a new school, trouble, or forgetting the day.', array['UNSUPPORTED_INFERENCE', 'EXPLICIT_STATEMENT_REQUIRED']::text[], 'pr-read-inf-general', 'q-read-inf-priya', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-math-frac-granola', 1, 'math', 5, 'math.fractions_intro', 'Comparing fractions with the same numerator', 'initial', null, 'Two granola bars are the same size. Jun eats 2/5 of one bar. Kim eats 2/3 of the other bar. Who eats more granola bar?', 'Explain how the size of the pieces helped you compare.', '[{"id":"A","text":"They eat the same amount."},{"id":"B","text":"Jun."},{"id":"C","text":"It cannot be determined."},{"id":"D","text":"Kim."}]'::jsonb, 'D', 'The bars are the same size. Thirds are larger than fifths, so two thirds is more than two fifths: 2/3 > 2/5.', array['LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT']::text[], 'pr-math-frac-general', 'q-math-frac-ribbon', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-math-frac-paint', 1, 'math', 5, 'math.fractions_intro', 'Comparing fractions with the same numerator', 'initial', null, 'Two walls are the same size. Omar paints 3/10 of one wall. Lila paints 3/6 of the other wall. Who paints more of a wall?', 'Explain how the size and number of parts helped you compare.', '[{"id":"A","text":"Lila."},{"id":"B","text":"Omar."},{"id":"C","text":"They paint the same amount."},{"id":"D","text":"It cannot be determined."}]'::jsonb, 'A', 'The walls are the same size. Sixths are larger than tenths, so three sixths is more than three tenths: 3/6 > 3/10.', array['LARGER_DENOMINATOR_MEANS_LARGER_AMOUNT', 'SAME_NUMERATOR_MEANS_EQUAL_AMOUNT']::text[], 'pr-math-frac-general', 'q-math-frac-garden', true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
insert into public.questions (id, version, subject, grade_level, skill, skill_focus, question_role, passage_id, prompt, reasoning_prompt, answer_choices, correct_answer, reference_explanation, allowed_misconceptions, practice_resource_id, follow_up_question_id, verified, owner_id, source) values ('q-read-main-amina', 1, 'reading', 5, 'reading.main_idea', 'Identifying the main idea of a short passage', 'initial', 'p-amina-seedlings', 'What is this passage mostly about?', 'What in the passage helped you decide?', '[{"id":"A","text":"Amina eats lunch with her class."},{"id":"B","text":"Amina takes care of the class seedlings."},{"id":"C","text":"Why windows get hot at lunchtime."},{"id":"D","text":"How to build a tray for plants."}]'::jsonb, 'B', 'Every sentence describes something Amina does for the seedlings: noticing them, watering them, checking the soil, and moving the tray.', '{}'::text[], null, null, true, null, 'seed') on conflict (id) do update set version = excluded.version, prompt = excluded.prompt, answer_choices = excluded.answer_choices, correct_answer = excluded.correct_answer, reference_explanation = excluded.reference_explanation, follow_up_question_id = excluded.follow_up_question_id, verified = excluded.verified;
